```java
import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 配送费与服务费计算工具类。
 * 纯 Java 实现，不涉及数据库、Web 接口或外部服务。
 */
public final class FeeCalculator {

    /** 配送费免收阈值：订单金额严格大于该值且件数大于 0 时免配送费。 */
    private static final BigDecimal DELIVERY_FREE_THRESHOLD = new BigDecimal("200");

    /** 配送费标准金额。 */
    private static final BigDecimal DELIVERY_FEE = new BigDecimal("12");

    /** 服务费低档金额。 */
    private static final BigDecimal SERVICE_FEE_LOW = new BigDecimal("2");

    /** 服务费高档金额。 */
    private static final BigDecimal SERVICE_FEE_HIGH = new BigDecimal("5");

    /** 服务费分档阈值：金额严格大于该值时进入高档。 */
    private static final BigDecimal SERVICE_FEE_THRESHOLD = new BigDecimal("100");

    /** 金额返回值统一保留的小数位数。 */
    private static final int SCALE = 2;

    private FeeCalculator() {
        // 工具类，禁止实例化
    }

    /**
     * 计算配送费。
     *
     * 规则：
     * - itemCount == 0 返回 0；
     * - itemCount > 0 且 amount 严格大于 200 返回 0；
     * - 其他情况（itemCount > 0 且 amount <= 200，含恰好 200）返回 12。
     *
     * @param amount    订单金额，单位元，不能为 null 且不能小于 0
     * @param itemCount 件数，不能小于 0
     * @return 配送费，保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null、amount 小于 0 或 itemCount 小于 0 时
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        validateAmount(amount);
        validateItemCount(itemCount);

        if (itemCount == 0) {
            return scale(BigDecimal.ZERO);
        }

        if (amount.compareTo(DELIVERY_FREE_THRESHOLD) > 0) {
            return scale(BigDecimal.ZERO);
        }

        return scale(DELIVERY_FEE);
    }

    /**
     * 计算服务费。
     *
     * 规则：
     * - amount == 0 返回 0；
     * - 0 < amount <= 100 返回 2；
     * - amount > 100 返回 5。
     * 服务费不使用配送费的 200 阈值。
     *
     * @param amount 订单金额，单位元，不能为 null 且不能小于 0
     * @return 服务费，保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null 或小于 0 时
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        validateAmount(amount);

        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return scale(BigDecimal.ZERO);
        }

        if (amount.compareTo(SERVICE_FEE_THRESHOLD) > 0) {
            return scale(SERVICE_FEE_HIGH);
        }

        return scale(SERVICE_FEE_LOW);
    }

    /**
     * 校验金额：不能为 null，且不能小于 0。
     */
    private static void validateAmount(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("amount must not be null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("amount must be greater than or equal to 0, but was " + amount);
        }
    }

    /**
     * 校验件数：不能小于 0。
     */
    private static void validateItemCount(int itemCount) {
        if (itemCount < 0) {
            throw new IllegalArgumentException("itemCount must be greater than or equal to 0, but was " + itemCount);
        }
    }

    /**
     * 统一保留 2 位小数，返回新的 BigDecimal，不修改入参。
     */
    private static BigDecimal scale(BigDecimal value) {
        return value.setScale(SCALE, RoundingMode.HALF_UP);
    }
}
