public class FeeCalculatorTest {

    public static void main(String[] args) {
        testDeliveryFee();
        testServiceFee();
        System.out.println("All tests passed.");
    }

    private static void testDeliveryFee() {
        // 件数0
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("0"), 0));
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("200"), 0));
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("200.01"), 0));

        // 件数1，金额严格大于200
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("200.01"), 1));
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("300"), 1));

        // 件数1，金额恰好200
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("200"), 1));

        // 件数1，金额小于200
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("199.99"), 1));
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("0"), 1));

        // 边界：金额0，件数1
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("0"), 1));

        // 异常：null金额
        try {
            FeeCalculator.deliveryFee(null, 1);
            throw new AssertionError("Expected IllegalArgumentException for null amount");
        } catch (IllegalArgumentException expected) {
        }

        // 异常：负金额
        try {
            FeeCalculator.deliveryFee(new BigDecimal("-0.01"), 1);
            throw new AssertionError("Expected IllegalArgumentException for negative amount");
        } catch (IllegalArgumentException expected) {
        }

        // 异常：负件数
        try {
            FeeCalculator.deliveryFee(new BigDecimal("10"), -1);
            throw new AssertionError("Expected IllegalArgumentException for negative itemCount");
        } catch (IllegalArgumentException expected) {
        }
    }

    private static void testServiceFee() {
        // 金额0
        assertEquals(new BigDecimal("0.00"), FeeCalculator.serviceFee(new BigDecimal("0")));

        // 0 < amount <= 100
        assertEquals(new BigDecimal("2.00"), FeeCalculator.serviceFee(new BigDecimal("0.01")));
        assertEquals(new BigDecimal("2.00"), FeeCalculator.serviceFee(new BigDecimal("100")));

        // amount > 100
        assertEquals(new BigDecimal("5.00"), FeeCalculator.serviceFee(new BigDecimal("100.01")));
        assertEquals(new BigDecimal("5.00"), FeeCalculator.serviceFee(new BigDecimal("200")));

        // 异常：null金额
        try {
            FeeCalculator.serviceFee(null);
            throw new AssertionError("Expected IllegalArgumentException for null amount");
        } catch (IllegalArgumentException expected) {
        }

        // 异常：负金额
        try {
            FeeCalculator.serviceFee(new BigDecimal("-0.01"));
            throw new AssertionError("Expected IllegalArgumentException for negative amount");
        } catch (IllegalArgumentException expected) {
        }
    }

    private static void assertEquals(BigDecimal expected, BigDecimal actual) {
        if (expected.compareTo(actual) != 0) {
            throw new AssertionError("Expected " + expected + " but got " + actual);
        }
    }
}
